import {SUPABASE_URL,SUPABASE_PUBLISHABLE_KEY,SCHOOL_NAME} from '../config.js';
import {createClient} from 'https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.57.0/+esm';
import {esc,dateBR,errorText,roleName,SCHOOL_EMAIL} from './utils.js';
const $=id=>document.getElementById(id);
if(!/^https:\/\/[a-z0-9]+\.supabase\.co$/.test(SUPABASE_URL)||!/^sb_publishable_/.test(SUPABASE_PUBLISHABLE_KEY))throw Error('Configuração inválida');
const db=createClient(SUPABASE_URL,SUPABASE_PUBLISHABLE_KEY,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});
const state={me:null,page:'overview',offset:0,rows:[],classes:[],selected:null,search:[],index:-1,historyStudent:'',request:null,report:null};
let reportFilter={kind:'students',class:'',grade:''};
let authMode='login',access='aluno',recovering=/(?:[?#&])type=recovery(?:[&#]|$)/.test(location.href),busy=false,renderToken=0,searchToken=0,authLoading=false;
const paths={overview:['Visão geral','O dia a dia da escola, em perspectiva.','M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z'],entry:['Registrar atraso','Pesquise, selecione e registre.','M12 8v4l3 2 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0'],students:['Alunos','Consulte a situação e o histórico de cada estudante.','M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M20 8v6 M17 11h6'],history:['Histórico','Ocorrências preservadas, com suas correções e justificativas.','M4 3h16v18H4z M8 8h8 M8 12h8 M8 16h5'],enrollments:['Matrículas','Autorize o cadastro e mantenha os dados escolares.','M4 4h16v16H4z M8 8h8 M8 12h8 M8 16h4'],classes:['Séries e turmas','Organização das turmas da unidade escolar.','M3 21V7l9-5 9 5v14 M9 21v-7h6v7 M7 9h1 M16 9h1'],team:['Equipe','Cadastros autorizados e permissões institucionais.','M4 21v-3a5 5 0 0 1 10 0v3 M13 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M17 4a4 4 0 0 1 0 8 M18 15a4 4 0 0 1 3 4v2'],adjustments:['Novas chances e ajustes','Decisões administrativas e seus motivos.','M4 5h16v14H4z M8 10h8 M12 6v8'],announcements:['Comunicados','Informações publicadas pela escola.','M3 10v4h4l11 5V5L7 10z M7 14l2 7'],archive:['Arquivo escolar','Alunos arquivados com histórico preservado.','M3 3h18v5H3z M5 8v13h14V8 M9 12h6'],period:['Período e regras','Configurações escolares e encerramento de períodos.','M4 5h16v16H4z M8 2v6 M16 2v6 M4 10h16'],audit:['Auditoria','Rastreabilidade das operações institucionais.','M5 3h14v18H5z M9 7h6 M9 12h6 M9 17h6'],reports:['Relatórios Excel','Relatórios por aluno, turma, série ou matrícula para uso institucional.','M4 4h16v16H4z M8 8h8 M8 12h8 M8 16h8'],privacy:['Privacidade','Solicitações e incidentes sob responsabilidade da Direção.','M12 2l8 4v6c0 5-8 10-8 10S4 17 4 12V6z M9 12l2 2 4-4']};
const staff=()=>Boolean(state.me && state.me.role!=='aluno');
const admin=()=>state.me?.role==='admin';
const studentView=()=>state.me?.role==='aluno';
const initials=name=>String(name||'').split(/\s+/).filter(Boolean).slice(0,2).map(part=>part[0]?.toUpperCase()||'').join('')||'??';
const cap=s=>String(s||'').charAt(0).toUpperCase()+String(s||'').slice(1);
function longDateBR(value=new Date()){const date=value instanceof Date?value:new Date(value);return new Intl.DateTimeFormat('pt-BR',{weekday:'long',day:'2-digit',month:'long',year:'numeric'}).format(date).replace(/,/,',').replace(/^./,m=>m.toUpperCase());}
const allowed=()=>state.me?.role==='aluno'?['overview','history','announcements']:admin()?Object.keys(paths):['overview','entry','students','history','enrollments','reports','announcements'];
let announcementFilter={query:'',type:'todos'};


function uiIcon(name){const map={graduation:'M2 10l10-6 10 6-10 6-10-6zm4 3v5c4 3 8 3 12 0v-5M22 10v6',menu:'M4 6h16 M4 12h16 M4 18h16',theme:'M12 2v2 M12 20v2 M4.93 4.93l1.42 1.42 M17.65 17.65l1.42 1.42 M2 12h2 M20 12h2 M4.93 19.07l1.42-1.42 M17.65 6.35l1.42-1.42 M12 17a5 5 0 1 0 0-10 5 5 0 0 0 0 10',refresh:'M20 11a8 8 0 0 0-14-5L3 9 M3 3v6h6 M4 13a8 8 0 0 0 14 5l3-3 M15 15h6v6',clock:'M12 7v5l3 3M12 21a9 9 0 1 0 0-18a9 9 0 0 0 0 18Z',limit:'M8 16V9m4 7V5m4 11v-8',history:'M8 7h8M8 12h8M8 17h6M6 4h12a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2Z',forgiven:'m9 12 2 2 4-5M12 21a9 9 0 1 0 0-18a9 9 0 0 0 0 18Z',announcement:'M3 10v4h4l11 5V5L7 10z M7 14l2 7',calendar:'M7 3v3M17 3v3M4 9h16M5 5h14a1 1 0 0 1 1 1v12a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a1 1 0 0 1 1-1Z',copy:'M9 9h10v10H9zM5 5h10v2H7v8H5z',chevron:'M9 6l6 6-6 6',quote:'M8.5 13H6.75A2.75 2.75 0 0 1 4 10.25V10a4 4 0 0 1 4-4m7.5 7h-1.75A2.75 2.75 0 0 1 11 10.25V10a4 4 0 0 1 4-4',bell:'M15 17h5l-1.4-1.4A2 2 0 0 1 18 14.2V11a6 6 0 1 0-12 0v3.2a2 2 0 0 1-.6 1.4L4 17h5m3 0v1a2 2 0 1 1-4 0v-1m4 0H8',users:'M16 21v-2a4 4 0 0 0-4-4H7a4 4 0 0 0-4 4v2M9 7a4 4 0 1 0 0-8a4 4 0 0 0 0 8Zm11 14v-2a4 4 0 0 0-3-3.87M14 3.13a4 4 0 0 1 0 7.75',alert:'M12 9v4m0 4h.01M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0Z',flag:'M5 4v16M5 5h11l-1.8 3L16 11H5',school:'M3 10l9-5 9 5-9 5-9-5Zm3 2.5V16c0 1.2 2.7 3 6 3s6-1.8 6-3v-3.5',search:'m21 21-4.35-4.35M10.5 18a7.5 7.5 0 1 1 0-15a7.5 7.5 0 0 1 0 15Z'};return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${map[name]||map.history}"/></svg>`;}
function renderPageProfile(){
 const el=$("pageProfile");
 if(!el||!state.me)return;
 const subtitle=studentView()?esc(state.me.grade||"Turma não informada"):esc(roleName(state.me.role));
 const displayName=studentView()?state.me.full_name.trim().split(/\s+/).slice(0,2).join(' '):state.me.full_name;
 const chip=studentView()&&state.me.ra?`<button type="button" class="profile-chip profile-chip-copy" data-copy-ra="${esc(state.me.ra)}" aria-label="Copiar RA"><span class="profile-ra-text">RA ${esc(state.me.ra)}</span><span class="profile-chip-icon">${uiIcon('copy')}</span></button>`:`<span class="profile-chip">Acesso ativo</span>`;
 el.innerHTML=`<div class="profile-avatar">${esc(initials(state.me.full_name))}</div><div class="profile-meta"><strong title="${esc(state.me.full_name)}">${esc(displayName)}</strong><span class="profile-subline"><span>${subtitle}</span><span class="status-dot" aria-hidden="true"></span></span>${chip}</div>`;
 const copyBtn=el.querySelector('[data-copy-ra]');
 if(copyBtn)copyBtn.onclick=async()=>{try{await navigator.clipboard.writeText(copyBtn.dataset.copyRa||'');msg('RA copiado.','success');}catch{msg('Não foi possível copiar o RA neste dispositivo.','error');}};
}
function renderHeaderChrome(){
 const utility=$("pageUtility"), status=$("pageStatusCard"), campus=$("sidebarCampus");
 if(!state.me)return;
 const staffOverview=staff()&&state.page==='overview';
 if(campus)campus.innerHTML=`<strong>${esc(SCHOOL_NAME)}</strong><small>PEI · Ensino de qualidade</small>`;
 if(utility){
   if(staffOverview)utility.innerHTML=`<form id="globalSearchForm" class="global-search"><label class="search-shell"><span class="search-icon">${uiIcon('search')}</span><input id="globalSearchInput" type="search" placeholder="Buscar aluno, turma ou ocorrência..." autocomplete="off"></label><button type="button" class="bell-button" aria-label="Ver comunicados da escola">${uiIcon('bell')}</button></form>`;
   else utility.innerHTML='';
   utility.querySelector('.bell-button')?.addEventListener('click',()=>{location.hash='#/announcements';});
   const form=$("globalSearchForm");
   if(form)form.onsubmit=e=>{e.preventDefault();const q=$("globalSearchInput")?.value?.trim()||'';if(!q)return;studentsFilter={...studentsFilter,search:q};location.hash='#/students';};
 }
 if(status){
   if(staffOverview)status.innerHTML=`<div class="status-card-icon">${uiIcon('calendar')}</div><div class="status-card-copy"><strong>${esc(longDateBR())}</strong><small>Ano letivo em andamento</small></div>`;
   else status.innerHTML='';
 }
}
function historyBadge(r){return `<span class="pill ${r.status==='void'?'ghost':r.status==='forgiven'?'ok':r.status==='active'?'warn':''}">${r.status==='forgiven'?'Perdoado':r.status==='void'?'Anulado':r.justified?'Justificado':'Válido'}</span>`;}
function renderStudentHistory(rows){
 const filters=`<section class="panel filters-card"><div class="section-head"><h3>Filtros</h3><button type="button" class="link-lite" data-action="clear-history-filters">Limpar filtros</button></div><form id="historyFilters" class="filters mobile-history-filters"><label>De<input id="fromDate" type="date" value="${esc(historyFilter.from||'')}"></label><label>Até<input id="toDate" type="date" value="${esc(historyFilter.to||'')}"></label><label>Situação<select id="historyStatus"><option value="">Todas</option><option value="active">Válidos</option><option value="forgiven">Perdoados</option><option value="void">Anulados</option></select></label><button type="submit" class="primary">Filtrar</button></form></section>`;
 const header=`<div class="section-inline"><h3>Resultados <span class="result-count">${rows.length} ${rows.length===1?'registro':'registros'}</span></h3></div>`;
 const cards=rows.length?`<div class="history-stack">${rows.map((r,i)=>`<article class="history-card"><div class="history-card-top"><div><small>Data</small><strong>${dateBR(r.occurred_at)}</strong></div><span class="history-code">#${String(state.offset+i+1).padStart(4,'0')}</span></div><div class="history-grid"><div><small>Situação</small>${historyBadge(r)}</div><div><small>Observação</small><p>${esc(r.reason||'—')}</p>${r.change_reason?`<small class="muted">Alteração: ${esc(r.change_reason)}</small>`:''}</div><div><small>Responsável</small><p>${esc(r.operator_name||'Registro legado')}</p></div></div></article>`).join('')}</div>`:'<div class="panel empty-card"><strong>Nenhum outro registro encontrado.</strong><p>Tente ajustar os filtros ou o período de busca.</p></div>';
 return filters+header+cards+pager(rows);
}
function announcementTone(r){
 const text=((r.title||'')+' '+(r.body||'')).toLowerCase();
 if(/atividade|prova|bimestre|trabalho|acad[eê]mic/.test(text))return ['Acadêmico','tone-academic'];
 if(/evento|reuni[aã]o|semana|feira|palestra|encontro/.test(text))return ['Evento','tone-event'];
 if(/urgente|aten[cç][aã]o|importante|respons[aá]veis|prazo/.test(text))return ['Importante','tone-important'];
 return ['Geral','tone-general'];
}
function renderAnnouncements(rows){
 const filtered=rows.filter(r=>{const [tone]=announcementTone(r);const hit=!announcementFilter.query||((r.title||'')+' '+(r.body||'')).toLowerCase().includes(announcementFilter.query.toLowerCase());const kind=announcementFilter.type==='todos'||tone.toLowerCase()===announcementFilter.type;return hit&&kind;});
 const chips=[['todos','Todos'],['importante','Importantes'],['acadêmico','Acadêmicos'],['evento','Eventos']];
 const tools=`<section class="panel filters-card"><form id="announcementFilters" class="announcement-tools"><label class="search-field">Buscar comunicados<input id="announcementSearch" type="search" value="${esc(announcementFilter.query||'')}" placeholder="Buscar comunicados…"></label><div class="chip-row">${chips.map(([value,label])=>`<button type="button" class="chip ${announcementFilter.type===value?'active':''}" data-announcement-type="${value}">${label}</button>`).join('')}</div></form></section>`;
 const actions=admin()?`<div class="toolbar">${button('Publicar comunicado','announcement-new','','primary')}</div>`:'';
 const cards=filtered.length?filtered.map(r=>{const [label,klass]=announcementTone(r);return `<article class="announcement-card ${klass}"><div class="announcement-meta"><span class="pill ${klass}">${label}</span><small>${dateBR(r.created_at)}</small></div><h3>${esc(r.title)}</h3><p>${esc(r.body)}</p><div class="announcement-actions">${!r.active?'<small>Arquivado</small>':''}${admin()?button('Editar','announcement-edit',r.id):''}</div></article>`;}).join(''):'<div class="panel empty-card"><strong>Nenhum comunicado.</strong><p>Quando houver novos comunicados, eles aparecerão aqui.</p></div>';
 return `<section class="panel announcement-shell">${actions}${tools}<div class="announcement-list">${cards}</div>${pager(rows)}</section>`;
}
function renderMobileNav(){
 const shortcuts=state.me.role==='aluno'?['overview','history','announcements']:['overview','entry','students','history'];
 $('mobileNav').hidden=false;
 $('mobileNav').innerHTML=shortcuts.filter(k=>allowed().includes(k)).map(k=>`<a data-page="${k}" href="#/${k}" aria-label="${paths[k][0]}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[k][2]}"/></svg><span>${k==='overview'?'Início':k==='entry'?'Atraso':paths[k][0]}</span></a>`).join('')+'<button type="button" id="mobileMore" aria-controls="sidebar" aria-expanded="false" aria-label="Mais opções">☰<span>Mais</span></button>';
 $('mobileMore').onclick=()=>toggleNavigation();
}
function closeNavigation(){
 $('sidebar').classList.remove('open');$('navScrim').hidden=true;
 $('menu').setAttribute('aria-expanded','false');$('mobileMore')?.setAttribute('aria-expanded','false');
}
function toggleNavigation(){
 const open=!$('sidebar').classList.contains('open');
 $('sidebar').classList.toggle('open',open);$('navScrim').hidden=!open;
 $('menu').setAttribute('aria-expanded',String(open));$('mobileMore')?.setAttribute('aria-expanded',String(open));
 if(open)$('sidebar').querySelector('a')?.focus();
}
$('navScrim').onclick=closeNavigation;
window.addEventListener('keydown',event=>{if(event.key==='Escape')closeNavigation();});
function msg(text,kind='success',target='flash'){const n=$(target);n.hidden=false;n.className='message '+kind;n.textContent=text;}
async function rpc(name,args){const {data,error}=await db.rpc(name,args);if(error){if(['PGRST301','PGRST303'].includes(error.code)){clearSession();msg('Sua sessão expirou. Entre novamente.','error','authMessage');}throw error;}return data;}
const read=(kind,args={})=>rpc('portal_read',{p_kind:kind,p_args:args});
const write=(action,args)=>rpc('portal_write',{p_action:action,p_args:args});
async function provisionEnrollment(id){const {data,error}=await db.functions.invoke('provision-student',{body:{enrollment_id:id}});if(error){let message='Matrícula salva, mas a criação da conta falhou. Tente novamente em Matrículas > Criar acesso.';try{const detail=await error.context?.json();if(detail?.error)message+=' '+String(detail.error).slice(0,160);}catch{}throw Error(message);}return data;}

function button(label,action,id='',cls='outline'){return `<button type="button" class="${cls}" data-action="${action}" data-id="${esc(id)}">${esc(label)}</button>`;}
function table(headers,rows){return rows.length?`<div class="table-scroll"><table class="responsive"><thead><tr>${headers.map(x=>`<th scope="col">${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(cells=>`<tr>${cells.map((v,i)=>`<td data-label="${esc(headers[i])}">${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nenhum registro encontrado.</div>';}
function pager(rows){return `<div class="pager">${button('Anterior','prev')}<span>Página ${state.offset/25+1}</span>${button('Próxima','next')}</div>`;}
function bindPager(rows){const p=$('view').querySelector('[data-action=prev]'),n=$('view').querySelector('[data-action=next]');if(p)p.disabled=state.offset===0;if(n)n.disabled=rows.length<25;}
const status=s=>`<span class="pill ${s.blocked?'block':s.unjustified_count>=s.late_limit-1?'warn':''}">${!s.enrollment_approved?'Matrícula pendente':s.blocked?'Limite atingido':s.unjustified_count>=s.late_limit-1?'Em atenção':'Regular'}</span>`;
function classesOptions(value='',all=true){return `${all?'<option value="">Todas as turmas</option>':'<option value="">Selecione</option>'}${state.classes.map(c=>`<option value="${esc(c.id)}" ${c.id===value?'selected':''}>${esc(c.grade+' • '+c.name)}${c.active?'':' (inativa)'}</option>`).join('')}`;}
const dataForm=form=>Object.fromEntries(new FormData(form));
function openModal(title,html,submit){$('modalBody').onclick=null;$('modalTitle').textContent=title;$('modalBody').innerHTML=html;$('modalError').hidden=true;$('modal').showModal();const form=$('modalBody').querySelector('form');if(form&&submit)form.onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;const btn=form.querySelector('[type=submit]');if(btn)btn.disabled=true;try{const outcome=await submit(dataForm(form));$('modal').close();if(outcome?.temporaryPassword){openModal('Acesso do aluno criado',`<p>Entregue os dados diretamente ao aluno. A senha é exibida apenas nesta tela e não é armazenada no portal.</p><p><strong>E-mail:</strong> ${esc(outcome.email)}</p><div class="credential-box" role="status">${esc(outcome.temporaryPassword)}</div><p class="credential-note">Oriente o aluno a alterar a senha no primeiro acesso por meio de Recuperar senha. Não encaminhe a senha em grupos ou planilhas.</p>`);}else msg(outcome?.linked?'Matrícula autorizada. Conta anterior vinculada; o aluno usa sua senha existente após confirmar o e-mail escolar.':'Alteração salva.');await render();}catch(err){msg(errorText(err),'error','modalError');}finally{busy=false;if(btn)btn.disabled=false;}};}
const field=(label,name,type='text',value='',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra} required></label>`;
const reasonField='<label>Justificativa<textarea name="reason" minlength="5" maxlength="500" required></textarea></label>';
const save='<button class="primary" type="submit">Salvar</button>';
async function reasonAction(title,action,args){openModal(title,`<form>${reasonField}${save}</form>`,d=>write(action,{...args,reason:d.reason}));}
function auth(next='login'){
 authMode=next;$('authView').hidden=false;$('dashboard').hidden=true;
 const signup=next==='signup',reset=next==='reset',recover=next==='recover';
 $('signupFields').hidden=!signup;$('studentSignup').hidden=access!=='aluno';$('consentField').hidden=!signup;
 $('emailField').hidden=reset;$('passwordField').hidden=recover;
 const form=$('authForm');form.elements.email.required=!reset;form.elements.password.required=!recover;
 form.elements.password.minLength=signup||reset?10:1;form.elements.password.autocomplete=signup||reset?'new-password':'current-password';
 form.elements.birth.disabled=!signup||access!=='aluno';
 $('emailField').firstChild.nodeValue=access==='aluno'?'E-mail escolar':'E-mail institucional';
 form.elements.email.placeholder=access==='aluno'?'0000111@al.educacao.sp.gov.br':'nome@instituicao.gov.br';
 $('accessExplain').textContent=access==='aluno'
  ?'Para alunos: use seu e-mail escolar e a senha. Se a secretaria já criou sua conta, entre com a senha provisória entregue por ela.'
  :'Para Secretaria e Direção: acesso exclusivo à equipe autorizada. Sua conta precisa de um convite da Direção.';
 $('authTitle').textContent={login:access==='aluno'?'Entrar como aluno':'Entrar como instituição',signup:access==='aluno'?'Solicitar acesso de aluno':'Ativar acesso da equipe',recover:'Recuperar senha',reset:'Definir nova senha'}[next];
 $('authSubtitle').textContent=signup?(access==='aluno'
  ?'Ainda não foi cadastrado pela secretaria? Solicite acesso com seu RA e confirme o e-mail escolar. Sua matrícula ficará aguardando aprovação da instituição.'
  :'Use somente o e-mail previamente convidado pela Direção e confirme a titularidade da conta.')
  :recover?'Enviaremos um link de recuperação para o e-mail cadastrado.'
  :access==='aluno'?'Acompanhe sua frequência e os comunicados da escola.':'Gerencie matrículas e registros conforme seu cargo.';
 $('authSubmit').textContent={login:'Entrar',signup:access==='aluno'?'Solicitar acesso':'Ativar conta institucional',recover:'Enviar link',reset:'Salvar nova senha'}[next];
 document.querySelectorAll('[data-auth]').forEach(b=>{b.hidden=(reset || (b.dataset.auth==='signup'&&next==='signup'));});
 document.querySelectorAll('[data-access]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.access===access)));
 $('authMessage').hidden=true;
}
$('authForm').onsubmit=async e=>{e.preventDefault();const btn=$('authSubmit');if(btn.disabled)return;btn.disabled=true;const d=dataForm(e.target),email=d.email?.trim().toLowerCase(),redirect=new URL('./',location.href).href;try{let result;if(authMode==='signup'){if(!d.consent)throw Error('Leia e confirme os Termos de Uso e a Política de Privacidade antes de solicitar acesso.');if(d.name.trim().length<3)throw Error('Informe o nome completo.');if(access==='aluno'&&(!SCHOOL_EMAIL.test(email)||!d.ra||!d.birth||!d.grade))throw Error('Informe RA, e-mail institucional, série, turma e nascimento.');const normalizedRA=String(d.ra||'').trim().toLowerCase().replace(/@al\.educacao\.sp\.gov\.br$/,'');if(access==='aluno'&&normalizedRA!==email.split('@')[0])throw Error('O RA informado precisa corresponder ao início do e-mail escolar.');result=await db.auth.signUp({email,password:d.password,options:{emailRedirectTo:redirect,data:{full_name:d.name.trim(),ra:access==='aluno'?normalizedRA:'',grade:d.grade,birth_date:d.birth}}});if(result.error)throw result.error;msg(access==='aluno'?'Solicitação recebida. Confirme o e-mail escolar e aguarde a escola autorizar sua matrícula. Se a secretaria já criou sua conta, use a senha fornecida ou recupere o acesso.':'Conta solicitada. Confirme o e-mail institucional. O convite da Direção deve estar válido.','success','authMessage');}
else if(authMode==='recover'){result=await db.auth.resetPasswordForEmail(email,{redirectTo:redirect});if(result.error)throw result.error;msg('Se o endereço estiver cadastrado, você receberá o link de recuperação.','success','authMessage');}
else if(authMode==='reset'){result=await db.auth.updateUser({password:d.password});if(result.error)throw result.error;recovering=false;await db.auth.signOut();auth();msg('Senha alterada. Entre com a nova senha.','success','authMessage');}
else{result=await db.auth.signInWithPassword({email,password:d.password});if(result.error)throw result.error;await loadSession();}}catch(err){msg(errorText(err),'error','authMessage');}finally{btn.disabled=false;}};
