async function loadSession(){if(authLoading||recovering)return;authLoading=true;try{const {data,error}=await db.auth.getUser();if(error||!data.user){state.me=null;auth();return;}state.me=await read('me');state.classes=await read('classes');$('authView').hidden=true;$('dashboard').hidden=false;document.body.classList.add('portal-layout');$('schoolLabel').textContent='Cada registro, uma história.';$('userName').textContent=state.me.full_name;$('userRole').textContent=roleName(state.me.role);$('avatar').textContent=initials(state.me.full_name);$('areaName').textContent='PAINEL '+roleName(state.me.role).toUpperCase();$('nav').innerHTML=allowed().map(k=>`<a href="#/${k}" data-page="${k}"><span class="nav-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="${paths[k][2]}"/></svg></span>${paths[k][0]}</a>`).join('');renderMobileNav();renderPageProfile();renderHeaderChrome();await route();}catch(err){state.me=null;auth();let notice=errorText(err);if(err?.code==='42501'){try{const pending=await rpc('portal_registration_status',{});if(pending==='aguardando_instituicao')notice='Solicitação recebida. Sua conta aguarda a autorização da matrícula pela secretaria. Você não tem acesso aos registros até a liberação.';else if(pending==='aguardando_email')notice='Confirme o e-mail escolar para ativar sua conta.';}catch{ /* mantém o erro original sem expor informações */ }}msg(notice,err?.code==='42501'?'success':'error','authMessage');}finally{authLoading=false;}}
